CREATE TABLE IF NOT EXISTS cyber_rule_candidates (
    id BIGSERIAL PRIMARY KEY,
    fingerprint TEXT NOT NULL UNIQUE,
    proposed_code TEXT NOT NULL,
    category TEXT NOT NULL,
    pattern TEXT NOT NULL,
    pattern_type TEXT NOT NULL DEFAULT 'regex' CHECK (pattern_type IN ('regex', 'contains', 'exact')),
    proposed_action TEXT NOT NULL DEFAULT 'review' CHECK (proposed_action IN ('block', 'review')),
    confidence DOUBLE PRECISION NOT NULL DEFAULT 0 CHECK (confidence BETWEEN 0 AND 1),
    model TEXT NOT NULL DEFAULT '',
    route_slug TEXT NOT NULL DEFAULT '',
    provider_error_class TEXT NOT NULL DEFAULT '',
    upstream_status INTEGER NOT NULL DEFAULT 0,
    reason TEXT NOT NULL DEFAULT '',
    evidence_count INTEGER NOT NULL DEFAULT 1 CHECK (evidence_count >= 1),
    distinct_users INTEGER NOT NULL DEFAULT 0 CHECK (distinct_users >= 0),
    status TEXT NOT NULL DEFAULT 'candidate' CHECK (status IN ('candidate','shadow','promoted','rejected')),
    promoted_rule_id BIGINT REFERENCES cyber_rules(id) ON DELETE SET NULL,
    first_seen_at TIMESTAMPTZ NOT NULL DEFAULT now(),
    last_seen_at TIMESTAMPTZ NOT NULL DEFAULT now(),
    updated_at TIMESTAMPTZ NOT NULL DEFAULT now()
);
-- statement-breakpoint
CREATE INDEX IF NOT EXISTS cyber_rule_candidates_status_seen_idx
ON cyber_rule_candidates (status,last_seen_at DESC);
-- statement-breakpoint
CREATE INDEX IF NOT EXISTS cyber_rule_candidates_category_idx
ON cyber_rule_candidates (category,last_seen_at DESC);
-- statement-breakpoint
CREATE TABLE IF NOT EXISTS cyber_rule_candidate_users (
    candidate_id BIGINT NOT NULL REFERENCES cyber_rule_candidates(id) ON DELETE CASCADE,
    user_digest TEXT NOT NULL,
    first_seen_at TIMESTAMPTZ NOT NULL DEFAULT now(),
    PRIMARY KEY (candidate_id,user_digest)
);
-- statement-breakpoint
ON CONFLICT (key) DO NOTHING;
-- statement-breakpoint
ON CONFLICT (code) DO UPDATE SET
    name=EXCLUDED.name,
    description=EXCLUDED.description,
    category=EXCLUDED.category,
    pattern=EXCLUDED.pattern,
    pattern_type=EXCLUDED.pattern_type,
    action=EXCLUDED.action,
    priority=EXCLUDED.priority,
    enabled=TRUE,
    updated_at=now();